window.__posterData({"id": "aida-javdan", "name": "Aida Javdan", "folder": "Week1_AI_Poster_AidaJavdan", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": ["<link href=\"https://fonts.googleapis.com/css2?family=Diplomata&display=swap\" rel=\"stylesheet\">"], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// 1. When i asked the AI to refactor the code, it made it much longer by adding a lot of global variables. Most of the code i understand as it is structurly very close to the one that i wrote and the functions are also very similar.\n\n// 2. I made the AI decrease the number of circles and add collision between the circles instead of the cursor and it works the way it should. The code uses Math.hypot() to calculate the distance between the centers of two circles. If that distance is smaller than the circles diameter, the circles are colliding. The speed of each circle changes depending on where they hit each other, if its vertical or horizontal the speed is greater than if its hit diagonally. \n\n// 3. I think the changes the AI made on its own, the lines that move back and forth, suit the poster and adds to it. They also use colors similar to the background image, which adds to the coherence. I thought that it was slightly boring, if i were to ask a an AI to make me something i would want it to make something that i coudnt make in a resonable time or something that i wount think of. If i cound add comments to it i would ask it to do something more impressive code-wise.  \n\n\n\n// SH RAVE POSTER\n// A button toggles moving circles (which bounce off the canvas edges and\n// each other) and triangles that move with a sine function.\n\n// ---------- Settings ----------\nconst CANVAS_W = 600;\nconst CANVAS_H = 800;\n\nconst CIRCLE_DIAMETER = 100;\nconst CIRCLE_SPEED = 5;\nconst CIRCLE_COUNT = 10;\nconst CIRCLE_COLORS = ['#ab03a966', '#ff467a6b', '#ffd51e57', '#00f7ff70'];\n\nconst TITLE = {\n  text: 'SH RAVE',\n  color: '#eb18a7',\n  size: 65,\n  font: 'Diplomata',\n  y: 60,\n};\n\nconst BUTTON_LABEL_START = 'Start Rave!';\nconst BUTTON_LABEL_END = 'End Rave :(';\nconst BUTTON_STYLE =\n  'padding: 20px; background:yellow; color: black; font-weight: bold; font-size: large';\n\nconst WAVE_SPEED = 0.05;\n\n// Laser beams sweeping up from the bottom centre\nconst LASER_COLORS = ['#ff2bd6', '#00f7ff', '#ffd51e', '#39ff14', '#ff467a'];\nconst LASER_SWING = 0.9;   // max angle (radians) away from straight up\nconst LASER_LENGTH = 1000; // longer than the canvas, so beams reach the edges\n\n// ---------- State ----------\nlet isRave = false;\nlet img;\nlet button;\nlet circles = [];\n\n// ---------- p5 lifecycle ----------\nasync function setup() {\n  createCanvas(CANVAS_W, CANVAS_H);\n  img = await loadImage('ufo.jpg');\n\n  circles = Array.from({ length: CIRCLE_COUNT }, createCircle);\n  createRaveButton();\n}\n\nfunction draw() {\n  background('black');\n  image(img, 0, 50, width, height);\n\n  drawTitle();\n\n  if (isRave) {\n    button.html(BUTTON_LABEL_END);\n    drawLasers();\n    drawTriangles();\n    drawCircles();\n  } else {\n    button.html(BUTTON_LABEL_START);\n  }\n}\n\n// ---------- Setup helpers ----------\nfunction createCircle() {\n  return {\n    x: random(CIRCLE_DIAMETER, CANVAS_W - CIRCLE_DIAMETER),\n    y: random(CIRCLE_DIAMETER, CANVAS_H - CIRCLE_DIAMETER),\n    speedX: CIRCLE_SPEED * random([1, -1]),\n    speedY: CIRCLE_SPEED * random([1, -1]),\n    color: random(CIRCLE_COLORS),\n  };\n}\n\nfunction createRaveButton() {\n  button = createButton(BUTTON_LABEL_START);\n  button.mousePressed(toggleRave);\n  button.position(CANVAS_W / 2 - textWidth(BUTTON_LABEL_START), CANVAS_H / 1.2);\n  button.style(BUTTON_STYLE);\n}\n\nfunction toggleRave() {\n  isRave = !isRave;\n}\n\n// ---------- Drawing ----------\nfunction drawTitle() {\n  fill(TITLE.color);\n  textAlign(CENTER);\n  textSize(TITLE.size);\n  textFont(TITLE.font);\n  text(TITLE.text, CANVAS_W / 2, TITLE.y);\n}\n\n// Laser beams that sweep back and forth, each with its own phase and colour\nfunction drawLasers() {\n  const t = frameCount * WAVE_SPEED;\n  const originX = CANVAS_W / 2;\n  const originY = CANVAS_H;\n\n  LASER_COLORS.forEach((laserColor, i) => {\n    const angle = -HALF_PI + sin(t + i * 1.3) * LASER_SWING;\n    const endX = originX + cos(angle) * LASER_LENGTH;\n    const endY = originY + sin(angle) * LASER_LENGTH;\n\n    // Wide, faint glow underneath a thin, bright core\n    stroke(color(laserColor + '33'));\n    strokeWeight(10);\n    line(originX, originY, endX, endY);\n\n    stroke(color(laserColor));\n    strokeWeight(2);\n    line(originX, originY, endX, endY);\n  });\n}\n\nfunction drawTriangles() {\n  fill('#136a459c');\n  stroke('#1dbe5e');\n  strokeWeight(1);\n\n  const w = CANVAS_W;\n  const h = CANVAS_H;\n  const move = sin(frameCount * WAVE_SPEED);\n\n  // Left side\n  triangle(0, h,\n           move * 20,             h * 0.5 + move * 20,\n           w * 0.15 + move * 30,  h * 0.6);\n  triangle(0, h,\n           w * 0.05 + move * 10,  h * 0.65 - move * 10,\n           w * 0.15 - move * 20,  h * 0.75 + move * 10);\n\n  // Right side (mirrored)\n  triangle(w, h,\n           w - move * 20,         h * 0.5 + move * 20,\n           w * 0.85 - move * 30,  h * 0.6);\n  triangle(w, h,\n           w * 0.95 - move * 10,  h * 0.65 - move * 10,\n           w * 0.85 + move * 20,  h * 0.75 + move * 10);\n}\n\nfunction drawCircles() {\n  strokeWeight(0);\n\n  for (const c of circles) {\n    fill(c.color);\n    circle(c.x, c.y, CIRCLE_DIAMETER);\n\n    moveCircle(c);\n    bounceOnEdges(c);\n  }\n\n  // Collisions between every pair of circles\n  for (let i = 0; i < circles.length; i++) {\n    for (let j = i + 1; j < circles.length; j++) {\n      collideCircles(circles[i], circles[j]);\n    }\n  }\n}\n\n// ---------- Circle behaviour ----------\nfunction moveCircle(c) {\n  c.x += c.speedX;\n  c.y += c.speedY;\n}\n\nfunction bounceOnEdges(c) {\n  const r = CIRCLE_DIAMETER / 2;\n\n  // Always point the speed away from the wall, so a circle that was pushed\n  // into a wall by a collision can't get stuck flipping every frame\n  if (c.x <= r) c.speedX = abs(c.speedX);\n  if (c.x >= CANVAS_W - r) c.speedX = -abs(c.speedX);\n  if (c.y <= r) c.speedY = abs(c.speedY);\n  if (c.y >= CANVAS_H - r) c.speedY = -abs(c.speedY);\n}\n\n// Elastic collision between two circles of equal size and mass\nfunction collideCircles(a, b) {\n  const dx = b.x - a.x;\n  const dy = b.y - a.y;\n  const dist = Math.hypot(dx, dy);\n\n  if (dist >= CIRCLE_DIAMETER || dist === 0) return;\n\n  // Collision normal (unit vector from a to b)\n  const nx = dx / dist;\n  const ny = dy / dist;\n\n  // Push the circles apart so they don't overlap\n  const overlap = (CIRCLE_DIAMETER - dist) / 2;\n  a.x -= nx * overlap;\n  a.y -= ny * overlap;\n  b.x += nx * overlap;\n  b.y += ny * overlap;\n\n  // Relative velocity along the normal; skip if already moving apart\n  const dvn = (a.speedX - b.speedX) * nx + (a.speedY - b.speedY) * ny;\n  if (dvn <= 0) return;\n\n  // Equal masses: exchange the velocity component along the normal\n  a.speedX -= dvn * nx;\n  a.speedY -= dvn * ny;\n  b.speedX += dvn * nx;\n  b.speedY += dvn * ny;\n}", "assets": {"ufo.jpg": {"mime": "image/webp", "b64": ""}}});
